   [37]={next_id=38, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="福登城——月夜之吻酒吧", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1303.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [38]={next_id=39, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="窗外天色暗沉，沉闷的雷声从云层深处滚过，细密的雨丝骤然倾泻而下，敲打在落地窗玻璃上，发出杂乱的声响，为静谧的夜晚平添几分压抑。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1303.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [39]={next_id=40, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="打烊的酒吧内褪去了平日的热闹，暖黄色的吊灯温柔洒落，隔绝了雨夜的湿冷，屋内暖意融融。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1303.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [40]={next_id=41, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="柔软的皮质沙发上，梅鹿特四肢舒展，百无聊赖地瘫躺着，手里把玩着一枚晶莹的源晶碎片，时不时扭头望向窗外的雨幕，语气里满是烦闷。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1303.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [41]={next_id=42, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="外面雨下这么大，也不知道尉官那边情况怎么样了。", msg_color="", msg_size=0, talker="梅鹿特", audio="", img="arts/ui/bg/story/storybg_1303.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4502", 0, 0, -129.5, 214.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [42]={next_id=43, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这都出去这么久了，一点消息都没有，该不会在大空洞遇到什么麻烦了吧……", msg_color="", msg_size=0, talker="梅鹿特", audio="", img="arts/ui/bg/story/storybg_1303.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4502", 0, 0, -129.5, 214.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
