   [44]={next_id=45, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="靠在吧台边上的歌海娜指尖捏着一杯猩红的果酒，猩红酒液在透明的杯壁内轻轻晃动。她长发松散垂落，眉眼清冷，原本慵懒松弛的神色，在听到梅鹿特的抱怨后，悄然凝滞几分。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1303.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4505", 0, 0, -3.5, 190.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [45]={next_id=46, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她下意识抬眸看向窗外瓢泼的大雨，脑海不受控制飘向数年前的福登城，一段尘封已久的雨夜记忆，缓缓浮出水面。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1303.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4505", 0, 0, -3.5, 190.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
