   [47]={next_id=48, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那也是这样一个暴雨倾盆的夜晚。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_409.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [48]={next_id=49, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="彼时的蛰吻初至繁华又混乱的福登城，她只是一个想要在地下世界站稳脚跟、给自己和身边流浪孩童一处安身之所的家主。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_409.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [49]={next_id=50, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="可福登城的地下势力早已被瓜分完毕，容不下任何新生势力。初来乍到的余烬经常与各大地下势力发生冲突，但就算各方势力联手却也拿蛰吻无可奈何。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_409.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [50]={next_id=51, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="为了拔除这个潜在的威胁，多家势力联合起来花重金委托歌海娜出手对付蛰吻。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_409.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [51]={next_id=52, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="雨夜窄巷，两个女人彼此对视着。就在刚刚，她们已经交手数轮，但都拿对方无可奈何。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_409.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [52]={next_id=53, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="最终歌海娜收起武器，在冰冷的雨幕里，对蛰吻说。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_409.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [53]={next_id=54, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我劝你尽早离开福登城。", msg_color="", msg_size=0, talker="歌海娜", audio="", img="arts/ui/bg/story/storybg_409.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4505", 0, 0, -3.5, 190.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [54]={next_id=55, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这里鱼龙混杂，利益早就被瓜分完了，已经没有多余的地盘留给新人。", msg_color="", msg_size=0, talker="歌海娜", audio="", img="arts/ui/bg/story/storybg_409.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4505", 0, 0, -3.5, 190.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [55]={next_id=56, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我的家人需要一块地方安生，福登城黑白两道皆存的状况是最佳场所。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_409.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223},{ 3, "4505", 0, 0, -3.5, 190.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
